var Arr=(input.trim()).split("\n");
while(true){
   var N=Arr.shift()-0;
   if(N==0)break;
   var n=[];
   var p=0;
   for(var i=0;i<N;i++)n[i]=0;
   var str=Arr.shift();
   for(var i=0;i<str.length;i++){
      var v=str[i];
      var j=i%N;
      if(v=="M")n[j]++;
      if(v=="S"){p+=(n[j]+1);n[j]=0;}
      if(v=="L"){n[j]+=(p+1);p=0;}
   }
   n.sort(function(a,b){return a-b;});
   console.log(n.join(" ")+" "+p);
}

